import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class HashMapRaceConditionDemo {
    public static void main(String[] args) throws InterruptedException {
        Map<String, String> unsafeMap = new HashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(4);

        for (int i = 0; i < 1000; i++) {
            final int taskId = i;
            executor.submit(() -> {
                unsafeMap.put("Key-" + taskId, "Value-" + taskId);
            });
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        // Size will often be less than 1000 due to lost updates (race conditions)
        System.out.println("Final map size: " + unsafeMap.size());
    }
}
